const item = $input.first().json.body || $input.first().json;

const imageUrl = item.imageUrl || '';
const base64Data = item.base64Data || '';
const mimeType = item.mimeType || 'image/jpeg';

const prompt = `Extract all details from this society expense receipt or invoice.
Return ONLY a JSON object with this exact structure:
{
  "merchantName": string,
  "invoiceNumber": string,
  "date": "YYYY-MM-DD",
  "currency": "INR" | "USD",
  "subtotal": number,
  "taxAmount": number,
  "totalAmount": number,
  "category": "Maintenance & Repairs" | "Utilities & Electricity" | "Security Services" | "Housekeeping & Cleaning" | "Gardening & Landscaping" | "Events & Celebrations" | "Office Supplies & Misc",
  "confidenceScore": number (0.0 to 1.0),
  "lineItems": [
    { "description": string, "quantity": number, "amount": number }
  ]
}`;

let parts = [{ text: prompt }];
if (base64Data) {
  parts.push({
    inline_data: {
      mime_type: mimeType,
      data: base64Data.replace(/^data:image\/\w+;base64,/, '')
    }
  });
}

return [{
  json: {
    expenseId: item.expenseId || item.id,
    parts
  }
}];

const geminiResponse = $input.first().json;
let parsedReceipt = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedReceipt = JSON.parse(rawText);
} catch (err) {
  parsedReceipt = {
    merchantName: "Unknown Vendor",
    totalAmount: 0,
    category: "Office Supplies & Misc",
    confidenceScore: 0.1
  };
}

const expenseId = $('Prepare Multimodal Prompt').first().json.expenseId;

return [{
  json: {
    status: "success",
    expenseId: expenseId,
    extractedAt: new Date().toISOString(),
    data: parsedReceipt
  }
}];
